CREATE FUNCTION public.grant_retained_admin(actor uuid, target uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ids uuid[]; BEGIN IF NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=actor AND role='admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; INSERT INTO public.purge_control(id,paused,preserve_user_ids) VALUES(true,true,ARRAY[actor]) ON CONFLICT DO NOTHING; SELECT preserve_user_ids INTO ids FROM public.purge_control WHERE id=true FOR UPDATE; IF cardinality(ids)=0 THEN ids:=ARRAY[actor]; END IF; IF NOT target=ANY(ids) THEN ids:=array_append(ids,target); END IF; IF cardinality(ids)<>2 OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE user_id=target) THEN RAISE EXCEPTION 'Two retained admins required'; END IF; INSERT INTO public.user_roles(user_id,role) VALUES(target,'admin') ON CONFLICT DO NOTHING; UPDATE public.profile_status SET is_admin=true WHERE user_id=target; UPDATE public.purge_control SET preserve_user_ids=ids,paused=true WHERE id=true; END $$;
REVOKE ALL ON FUNCTION public.grant_retained_admin(uuid,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.grant_retained_admin(uuid,uuid) TO service_role;
CREATE FUNCTION public.set_purge_paused(value boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ids uuid[]; BEGIN SELECT preserve_user_ids INTO ids FROM public.purge_control WHERE id=true FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Missing control'; END IF; IF NOT value AND (cardinality(ids)<>2 OR (SELECT count(*) FROM public.user_roles WHERE user_id=ANY(ids) AND role='admin')<>2) THEN RAISE EXCEPTION 'Two retained admins required'; END IF; UPDATE public.purge_control SET paused=value WHERE id=true; END $$;
REVOKE ALL ON FUNCTION public.set_purge_paused(boolean) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.set_purge_paused(boolean) TO service_role;